var e={"profile.title":`Dein Pseudonym`,"profile.desc":`Wird verwendet, wenn deine Web-Nachrichten nach Telegram kopiert werden (nicht unter deinen Nachrichten in den Sitzungen angezeigt).`,"profile.name":`Name`,"profile.nameDesc":`Maximal 32 Zeichen. Leer: kein Pseudonym.`,"profile.namePlaceholder":`z. B. Alex`,"profile.photo":`Foto`,"profile.photoDesc":`Wird statt Farbe und Emoji angezeigt, hier und bei deinen Team-Kontakten. Bleibt auf diesem Server gespeichert.`,"profile.photoError":`Dieses Bild kann hier nicht gelesen werden: Versuche es mit JPEG oder PNG.`,"profile.photoAdd":`Foto hinzufügen`,"profile.photoChange":`Ändern`,"profile.photoRemove":`Entfernen`,"profile.color":`Farbe`,"profile.colorDesc":`Die Farbe deines Badges (wenn kein Foto vorhanden ist).`,"profile.emoji":`Emoji`,"profile.emojiDesc":`Wird in deinem Badge statt deiner Initialen angezeigt (optional, wenn kein Foto vorhanden ist).`,"profile.preview":`Vorschau`,"profile.previewText":`Hi! Bereit, wenn du es bist.`,"profile.you":`Du`,"register.desc":`Alles ist optional. Was dieser Server den Autoren von Harness Maxxing mitteilt und wie du es stoppst.`,"register.email":`E-Mail (optional)`,"register.emailPlaceholder":`du@beispiel.de`,"register.emailDesc":`Nur um dich vor einem Sicherheitsproblem oder einer größeren Änderung zu warnen. Nie weitergegeben, nie verkauft.`,"register.emailInvalid":`Das sieht nicht nach einer E-Mail-Adresse aus.`,"register.news":`Schick mir auch die Neuigkeiten zum Produkt`,"register.newsDesc":`Neue Funktionen, höchstens ein paar Mal im Monat. Du kannst dich hier jederzeit abmelden.`,"register.count":`Beim Zählen der Installationen helfen (anonym)`,"register.countDesc":`Einmal am Tag: eine Zufallszahl, die Version, das System (z. B. Ubuntu 24.04, x86_64) und ein paar Gesundheitscodes (Dienst aktiv, Claude angemeldet, letztes Update fehlgeschlagen …). Kein Name, keine E-Mail, keine IP, kein Servername, keine Inhalte.`,"register.countBlocked":`Auf diesem Server durch MAXXING_NO_TELEMETRY oder DO_NOT_TRACK in der Dienstumgebung deaktiviert.`,"register.privacy":`Wird an api.harness-maxxing.com gesendet. Dein Pseudonym und deine Sprache werden nur mit einer E-Mail gesendet. Wenn du alles abwählst, wird nichts mehr gesendet: Wir kontaktieren diesen Server nie wieder.`,"register.statusOff":`Dieser Server teilt den Autoren nichts mit.`,"register.statusOn":`Registriert. Ein Signal pro Tag.`,"register.statusPending":`Noch nicht gesendet: Das passiert beim nächsten täglichen Signal.`,"register.statusError":`Die Autoren konnten nicht erreicht werden: {error}. Morgen gibt es einen neuen Versuch.`,"register.stop":`Stopp, nicht mehr kontaktieren`,"license.title":`Enterprise-Lizenz (optional)`,"license.desc":`Harness Maxxing ist kostenlos für dich selbst und für eine Organisation, die es für den eigenen Bedarf nutzt. Ein Schlüssel ist nur für Unternehmen, die einen brauchen; an der Funktionsweise ändert er nichts.`,"license.read":`Lizenz lesen`,"license.whoTitle":`Wer braucht einen Schlüssel?`,"license.who1":`Eine Organisation, die es für ihre Tochtergesellschaften, Konzernunternehmen oder Kunden nutzt.`,"license.who2":`Ein kostenpflichtiges Angebot, das es enthält: Weiterverkauf, Hosting, kostenpflichtige Installation oder Support.`,"license.whoNot":`Sonst niemand: Privatpersonen, Selbstständige und Organisationen für den eigenen Bedarf müssen nichts tun.`,"license.get":`Enterprise-Lizenz anfragen`,"license.key":`Lizenzschlüssel`,"license.keyDesc":`Wird von harness-maxxing.com geprüft (ein Schlüssel = ein Server). Sonst ändert sich nichts: Updates kommen weiterhin von GitHub.`,"license.invalid":`Ein Schlüssel sieht so aus: HM-XXXX-XXXX-XXXX-XXXX.`,"license.save":`Schlüssel speichern`,"license.none":`Kein Schlüssel gespeichert: Das ist normal, solange keiner der oben genannten Fälle auf dich zutrifft.`,"license.active":`Schlüssel {key} ({kind})`,"license.until":`bis {date}`,"license.remove":`Schlüssel entfernen`,"license.removeDesc":`Gibt seinen Platz für einen anderen Server frei.`,"license.onbToggle":`Ich habe einen Enterprise-Lizenzschlüssel`,"license.onbToggleDesc":`Optional, nur für Unternehmen, die einen haben. Später änderbar unter Einstellungen -> Über.`,"tint.neutral":`Neutral`,"tint.tinted":`Akzentfarbton`,"fonts.group.modern":`Modern`,"fonts.group.character":`Mit Charakter`,"fonts.group.rounded":`Abgerundet`,"fonts.group.serif":`Serifen`,"fonts.group.readable":`Gut lesbar`,"fonts.group.mono":`Monospace`,"fonts.group.system":`Dieses Gerät`,"density.comfortable":`Komfortabel`,"density.compact":`Kompakt`,"accent.clay":`Orange`,"accent.blue":`Blau`,"accent.violet":`Violett`,"accent.green":`Grün`,"accent.amber":`Gelb`,"accent.rose":`Rot`,"system.address":`Adresse und Dateien`,"security.change":`Passwort ändern`,"security.changeDesc":`Wenn du das Passwort änderst, werden alle anderen Geräte abgemeldet.`,"security.current":`Aktuelles Passwort`,"security.currentRequired":`Gib dein aktuelles Passwort ein.`,"security.currentWrong":`Das aktuelle Passwort ist falsch.`,"security.update":`Passwort aktualisieren`,"security.changed":`Passwort geändert`,"security.changedDesc":`Andere Geräte wurden abgemeldet.`,"security.sessions":`Angemeldete Geräte`,"security.sessionsDesc":`Anmeldewarnungen können an Telegram gesendet werden (Einstellungen › Telegram).`,"security.status":`Schutzmaßnahmen`,"security.statusDesc":`Was diesen Server schützt und was noch zu aktivieren ist.`,"security.everywhere":`Um dich überall abzumelden, ändere dein Passwort: Alle bestehenden Sitzungs-Cookies funktionieren sofort nicht mehr.`,"security.app":`Authenticator-App`,"security.appDesc":`Nach dem Passwort fragt ein neuer Browser nach dem 6-stelligen Code einer App (Aegis, 2FAS, Google Authenticator…). Funktioniert ohne Telegram; wenn beides aktiv ist, genügt eines von beiden. Notausgang ohne Oberfläche: maxxing 2fa off auf dem Server.`,"security.appOn":`Die Authenticator-App ist aktiviert.`,"security.appOff":`Die Authenticator-App ist deaktiviert.`,"security.appPwDesc":`Gib zum Starten dein aktuelles Passwort ein.`,"security.appScan":`Scanne diesen Code mit deiner App oder gib den Schlüssel von Hand ein und trage dann den 6-stelligen Code ein, den die App anzeigt. Bis dieser Code akzeptiert wird, ändert sich nichts.`,"security.appOpen":`In einer App auf diesem Gerät öffnen`,"security.appKey":`Schlüssel`,"security.appCode":`6-stelliger Code`,"security.appBadCode":`Falscher Code.`,"security.appContinue":`Weiter`,"security.appTurnOn":`Aktivieren`,"security.appOffTitle":`Authenticator-App deaktivieren`,"security.appOffDesc":`Gib dein aktuelles Passwort und einen Code der App (oder einen Wiederherstellungscode) ein.`,"security.appOffCode":`App-Code oder Wiederherstellungscode`,"security.recovery":`Wiederherstellungscodes`,"security.recoveryDesc":`Noch {n} übrig. Jeder ersetzt einmalig einen Code der zweiten Stufe, wenn Telegram oder deine App nicht erreichbar ist.`,"security.recoveryNew":`Neue Codes`,"security.recoveryNewDesc":`Gib dein aktuelles Passwort ein. Die bisherigen Codes funktionieren dann nicht mehr.`,"security.recoveryTitle":`Deine Wiederherstellungscodes`,"security.recoverySave":`Bewahre sie sicher auf: Sie werden nur einmal angezeigt. Jeder Code funktioniert nur einmal; ältere Codes funktionieren nicht mehr.`,"security.recoverySaved":`Ich habe sie gespeichert`,"security.brThis":`Dieser Browser`,"security.brSeen":`Zuletzt gesehen {when}`,"security.brDisconnect":`Abmelden`,"security.brOthers":`Alle anderen abmelden`,"security.brOthersDone":`Alle anderen Browser wurden abgemeldet.`,"security.brLegacy":`Vor dieser Version angemeldete Browser`,"security.brLegacyDesc":`Sie haben keine eigene Zeile: „Alle anderen abmelden“ meldet sie ab.`,"cdef.defaultModel":`Standardmodell`,"cdef.cliDefault":`Standard von Claude Code`,"cdef.defaultModelHint":`Sitzungen zeigen das Modell an, das jeden Durchlauf tatsächlich beantwortet hat.`,"cdef.autoCompact":`Automatische Komprimierung`,"cdef.autoCompactHint":`Endet ein Durchlauf mit mehr Kontext als diesem Wert, fasst Harness die Sitzung zusammen und macht in einem neuen Verlauf weiter, der mit der Zusammenfassung beginnt (wie Komprimieren): Lange Sitzungen senden nicht mehr ihren ganzen Verlauf erneut, das spart Tokens. Der Verlauf bleibt sichtbar.`,"cdef.autoCompactOff":`Aus`,"cdef.autoCompactRecommended":`empfohlen`,"cdef.idleCompact":`Beim Zurückkommen komprimieren`,"cdef.idleCompactHint":`Der Prompt-Cache von Claude hält ein paar Minuten (höchstens eine Stunde). Schreibst du in eine Sitzung, die länger inaktiv war und mindestens so viel Kontext hat, fasst Harness sie zuerst zusammen, und deine Nachricht läuft in einem neuen Verlauf, der mit der Zusammenfassung beginnt: Der Verlauf würde ohnehin zum vollen Preis erneut gesendet, spätere Durchläufe werden so viel günstiger. Kostet einen Zusammenfassungs-Durchlauf (kurze Wartezeit) vor der Antwort.`,"cdef.smartResume":`Intelligentes Fortsetzen`,"cdef.smartResumeHint":`Kommst du zu einer Sitzung zurück, deren Cache abgelaufen ist (siehe oben) und die mindestens so viel Kontext hat, oder nach 5 Minuten oder mehr bei doppelt so viel, lässt Harness Claude die Sitzung zuerst passend zu der Nachricht zusammenfassen, die du gerade gesendet hast: Die Zusammenfassung behält genau das, was deine Nachricht braucht (Dateien, Befehle, Werte, den laufenden Plan), und deine Nachricht läuft dann in einem neuen, deutlich kleineren Verlauf. An echten Wiedereinstiegen gemessen: 38 bis 67 % weniger Tokens ab 100k und besser erhaltene Details als bei der einfachen Zusammenfassung. Aus = nur die Regel oben.`,"cdef.protectSecrets":`Geheimnisse schützen`,"cdef.protectSecretsHint":`Die Tools von Claude weigern sich, die Geheimnisse des Servers (secrets.json) und die SSH-Schlüssel (~/.ssh) zu lesen oder zu ändern, unabhängig vom Berechtigungsmodus. So kann eine in einer Webseite oder E-Mail versteckte Anweisung sie nicht einfach lesen; ein Skript, das die Datei öffnet, wird nicht gestoppt - bei Inhalten von außen wähle für dieses Thema lieber einen strengeren Berechtigungsmodus.`,"cdef.shortTitles":`Kurze Sitzungstitel`,"cdef.shortTitlesHint":`Eine neue Sitzung wird anhand ihrer ersten Nachricht in wenigen Wörtern benannt (ohne Begrüßungen und „kannst du…“). Aus: Der Titel ist der Anfang der Nachricht. Eine manuelle Umbenennung hat immer Vorrang.`,"cdef.shortTitlesModel":`Von Claude geschriebene Titel`,"cdef.shortTitlesModelHint":`Das kleinste Modell benennt das Thema (treffendere Titel). Ein kurzer Aufruf pro neuer Sitzung, wird auf deinen Claude-Tarif angerechnet.`,"cdef.autoUpdate":`Claude Code automatisch aktualisieren`,"cdef.autoUpdateHint":`Standardmäßig aus. An: Erscheint eine neuere stabile Version von Claude Code (eine, die schon einige Tage im Einsatz ist, nicht die allerneueste), installiert der Server sie, sobald 10 Minuten nichts gelaufen ist (kein Durchlauf, keine Nachricht in der Warteschlange, kein geplanter Job), und kehrt zur vorherigen zurück, falls sie nicht startet. Prüfung alle 6 Stunden; das Ergebnis erscheint in den Benachrichtigungen.`,"cdef.autoUpdateLast":`Letztes Update: {from} → {to}, {date}`,"cdef.autoUpdateFailed":`Update auf {to} fehlgeschlagen ({date})`,"telegram.setup":`Telegram einrichten`,"telegram.setupDesc":`Etwa zwei Minuten. Du brauchst die Telegram-App auf deinem Smartphone oder Computer.`,"telegram.sub.bot":`Bot`,"telegram.sub.link":`Verknüpfung`,"telegram.sub.threads":`Threads`,"telegram.bf1":`Öffne in Telegram`,"telegram.bf2":`Sende den Befehl:`,"telegram.bf3":`Wähle einen Anzeigenamen und dann einen Benutzernamen, der auf „bot“ endet (z. B. acme_maxxing_bot).`,"telegram.bf4":`BotFather antwortet mit einem Token wie 123456789:AAH…: Kopiere es und füge es unten ein.`,"telegram.token":`Bot-Token`,"telegram.tokenHint":`Wird auf diesem Server gespeichert. Wer den Token hat, steuert den Bot.`,"telegram.tokenRequired":`Füge den Token von BotFather ein.`,"telegram.tokenInvalid":`Telegram hat diesen Token abgelehnt.`,"telegram.verify":`Token prüfen`,"telegram.botOk":`Bot geprüft`,"telegram.linkIntro":`Verknüpfe jetzt dein Telegram-Konto: Nur der verknüpfte Chat kann mit Harness sprechen.`,"telegram.link":`Mein Telegram verknüpfen`,"telegram.qr":`QR-Code zum Öffnen des Bots`,"telegram.scan":`Mit dem Handy scannen`,"telegram.openAndStart":`Öffne den Bot und tippe auf Start. Diese Seite aktualisiert sich von selbst, sobald die Verknüpfung steht.`,"telegram.openTelegram":`In Telegram öffnen`,"telegram.waiting":`Warte auf /start…`,"telegram.manualCode":`Oder sende diese Nachricht an den Bot:`,"telegram.chatLinked":`Chat verknüpft`,"telegram.simpleIntro":`Ein einziger Chat zum Verfolgen: Schreibe eine Nachricht, um eine Sitzung zu starten (der Bot fragt, in welchem Thema), antworte auf eine Nachricht, um ihre Sitzung fortzusetzen. Die Warnungen kommen auch dort an. Stattdessen ein Thread pro Sitzung: Einstellungen › Telegram › Modus.`,"telegram.threadsIntro":`Jede offene Sitzung bekommt ihren eigenen Thread (dazu Crons und Warnungen). Archivierst du eine Sitzung, verschwindet ihr Thread; schreibe im Haupt-Chat, um eine neue zu starten.`,"telegram.created":`{count} Threads erstellt`,"telegram.created#one":`{count} Thread erstellt`,"telegram.topicsOff":`Threads sind für diesen Bot deaktiviert`,"telegram.topicsOff1":`Öffne @BotFather und sende /mybots, dann wähle deinen Bot.`,"telegram.topicsOff2":`Bot Settings › Threaded Mode › aktiviere ihn.`,"telegram.topicsOff3":`Komm hierher zurück und tippe auf „Erneut versuchen“.`,"telegram.noThreads":`Noch keine Threads.`,"telegram.thread.general":`Allgemein`,"telegram.thread.crons":`Berichte der geplanten Jobs`,"telegram.thread.alerts":`Warnungen`,"telegram.thread.feed":`Benachrichtigungen`,"telegram.status":`Status`,"telegram.gateway":`Gateway`,"telegram.running":`Aktiv`,"telegram.stopped":`Gestoppt`,"telegram.bot":`Bot`,"telegram.chat":`Verknüpfter Chat`,"telegram.test":`Testnachricht senden`,"telegram.testSent":`Testnachricht gesendet`,"telegram.behaviour":`Verhalten`,"telegram.mode":`Modus`,"telegram.modeDesc":`Wie der Telegram-Chat organisiert ist. Agenten mit der Telegram-Option behalten in jedem Modus ihren eigenen Thread.`,"telegram.mode.simple":`Einfach`,"telegram.mode.simple.desc":`Ein einziger Chat zum Verfolgen: die Warnungen und deine Sitzungen als Antworten. Schreibe eine Nachricht und wähle ihr Thema; antworte auf eine Nachricht, um ihre Sitzung fortzusetzen.`,"telegram.mode.threads":`Ein Thread pro Sitzung`,"telegram.mode.threads.desc":`Jede offene Sitzung der Web-Oberfläche bekommt ihren eigenen Thread, dazu Threads für Crons, Warnungen und Benachrichtigungen.`,"telegram.mode.mirror":`Threads + Web-Unterhaltungen`,"telegram.mode.mirror.desc":`Ein Thread pro Sitzung, in dem auch das, was du in der Web-Oberfläche schreibst, und die Antworten von Harness erscheinen, lautlos.`,"telegram.mode.needsThreads":`Aktiviere den Threaded Mode für den Bot in @BotFather: Bis dahin funktioniert der Chat im Modus Einfach.`,"telegram.mode.recommended":`empfohlen`,"telegram.modeConfirm":`{count} Threads aus Telegram löschen?`,"telegram.modeConfirm#one":`{count} Thread aus Telegram löschen?`,"telegram.modeConfirmDesc":`Die Sitzungs-Threads sowie die Threads für Crons, Warnungen und Benachrichtigungen werden samt ihren Nachrichten aus Telegram gelöscht. Die Sitzungen bleiben in der Web-Oberfläche; Agenten behalten ihre Threads.`,"telegram.modeConfirmOk":`Zu Einfach wechseln`,"telegram.notifySystem":`Server-Warnungen`,"telegram.notifySystemDesc":`Probleme des Servers (Speicherplatz, Dienste, Claude-Anmeldung, Backup, Updates), mit einer Schaltfläche „Gesehen“.`,"telegram.agentThreads":`Threads der Agenten`,"telegram.agentThreadsDesc":`Agenten mit der Telegram-Option veröffentlichen ihre Ergebnisse in ihrem eigenen Thread.`,"telegram.notifyCrons":`Berichte der geplanten Jobs`,"telegram.notifyCronsDesc":`Ergebnisse geplanter Jobs veröffentlichen (es gelten die Einstellungen pro Job; Fehler lösen einen Ton aus).`,"telegram.loginAlerts":`Anmeldewarnungen`,"telegram.loginAlertsDesc":`Nachricht bei jeder Anmeldung und lauter Alarm nach mehrfach falschem Passwort.`,"telegram.replyMode":`Antworten`,"telegram.replyModeDesc":`Live-Fortschritt: Eine Statusnachricht wird aktualisiert, während Harness arbeitet (Aufgabenliste und jeder Schritt) und am Ende zu einer Zusammenfassung eingeklappt. Oder nur die endgültige Antwort.`,"telegram.reply.final":`Endgültige Antwort`,"telegram.reply.progress":`Live-Fortschritt`,"trash.title":`Papierkorb`,"trash.desc":`Gelöschte Dateien, Themen, Projekte und Sitzungen. Stelle sie an ihrem ursprünglichen Ort wieder her oder lösche sie endgültig. Elemente, die älter als {days} Tage sind, werden automatisch entfernt.`,"trash.kind.file":`Datei`,"trash.kind.folder":`Ordner`,"trash.kind.topic":`Thema`,"trash.kind.project":`Projekt`,"trash.kind.session":`Sitzung`,"trash.kind.previous_versions":`frühere Versionen`,"trash.sessions":`{count} Sitzungen`,"trash.root":`Wurzelverzeichnis des Workspace`,"trash.restore":`Wiederherstellen`,"trash.restored":`Wiederhergestellt in {path}`,"trash.deleteForever":`Endgültig löschen`,"trash.deleteConfirm":`„{name}“ endgültig löschen?`,"trash.deleteDesc":`Das kann nicht rückgängig gemacht werden.`,"trash.empty":`Papierkorb leeren`,"trash.emptyConfirm":`Papierkorb leeren?`,"trash.emptied":`Papierkorb geleert`,"trash.none":`Der Papierkorb ist leer`,"trash.noneDesc":`Gelöschte Dateien, Themen und Sitzungen landen hier.`,"packs.title":`Startprojekte`,"packs.desc":`Fertige Projekte für eine Art von Arbeit: Jedes Thema kennt die Aufgabe bereits (ein Playbook) und stellt dir in der ersten Sitzung ein paar Fragen. Keine erfundenen Daten. Du kannst ein Paket beliebig oft hinzufügen: Jedes Mal entsteht ein neues Projekt (ecommerce-2 für einen zweiten Shop...). Nichts Bestehendes wird je überschrieben.`,"packs.restore":`Wieder einsetzen`,"packs.restored":`{count} Dateien wiederhergestellt`,"packs.nothingMissing":`Es fehlte nichts`,"packs.add":`Hinzufügen`,"packs.added":`Hinzugefügt`,"packs.jobs":`Geplante Jobs deaktiviert erstellt: {list}`,"packs.done":`{name} hinzugefügt ({count} Themen)`,"packs.doneMany":`{count} Projekte hinzugefügt`,"packs.doneMany#one":`{count} Projekt hinzugefügt`,"packs.all":`Alle installieren`,"packs.choose":`Auswählen`,"packs.none":`Keine`,"import.title":`Von einem anderen Agent importieren`,"import.desc":`Hermes, Claude Code, OpenClaw oder ein anderer Agent: Er exportiert, was er über dich weiß, als Projekte und Themen, und du legst die ZIP-Datei hier ab. Nichts Vorhandenes wird überschrieben.`,"import.agent":`Dein aktueller Agent`,"import.agentFile":`Ein Agent`,"import.other":`Andere`,"import.more":`Weitere Importe`,"import.step1":`Kopiere diesen Prompt und schicke ihn an deinen aktuellen Agent. Er erstellt eine ZIP-Datei mit deinen Projekten, Themen, deinem Gedächtnis und deinen Skills.`,"import.step2":`Lege die ZIP-Datei ab, die er dir gibt (oder klicke, um sie auszuwählen). Du siehst, was sie enthält, bevor etwas importiert wird.`,"import.drop":`Lege die .zip-Datei hier ab oder klicke, um sie auszuwählen`,"import.reading":`ZIP-Datei wird gelesen…`,"import.projects":`Projekte`,"import.topics":`Themen`,"import.skills":`Skills`,"import.files":`Dateien · {size}`,"import.new":`neu`,"import.merge":`vorhanden - zusammengeführt`,"import.rootMemory":`Dein Profil und deine Präferenzen (Gedächtnis des Workspace)`,"import.aside":`Für Harness aufbewahrt`,"import.neverOverwrite":`Vorhandene Gedächtnisdateien erhalten einen Abschnitt „Importiert“, andere vorhandene Dateien bleiben erhalten und die importierte Kopie wird daneben gespeichert.`,"import.secrets":`{count} Dateien abgelehnt: Sie enthalten einen Schlüssel oder ein Token`,"import.secretsHint":`Füge deine Schlüssel stattdessen unter Einstellungen → Schlüssel hinzu - niemals in Gedächtnisdateien.`,"import.skipped":`{count} Dateien übersprungen`,"import.apply":`Importieren`,"import.done":`Importiert: {projects} Projekte, {topics} Themen, {files} Dateien.`,"import.mergedInto":`{count} vorhandene Gedächtnisdateien haben einen Abschnitt „Importiert“ erhalten.`,"import.finish":`Harness den Import abschließen lassen`,"import.finishTitle":`Import abschließen`,"import.finishHint":`Harness ordnet das importierte Gedächtnis, erstellt deine Aufgaben, schlägt deine geplanten Jobs vor und listet die Schlüssel auf, die du hinzufügen musst.`,"import.finishing":`Harness schließt den Import ab (Aufgaben, geplante Jobs, hinzuzufügende Schlüssel) - du findest ihn unter Sitzungen.`,"import.copy":`Prompt kopieren`,"import.copied":`Kopiert`,"import.skillsN":`Skills`,"trash.loadFailed":`Papierkorb konnte nicht geladen werden`,"trash.loadFailedDesc":`Prüfe deine Verbindung oder deine Zugriffsrechte und versuche es dann erneut.`,"telegram.threads":`Threads`,"telegram.threadsDesc":`Einer pro offener Sitzung, automatisch synchronisiert. Wenn du einen Thread in Telegram löschst, wird seine Sitzung archiviert (nichts geht verloren).`,"telegram.threadDays":`Thread behalten für`,"telegram.threadDaysDesc":`Offene Sitzungen, die länger inaktiv sind, verlieren ihren Thread (sie bleiben in der Web-Oberfläche und bekommen ihn mit der nächsten Nachricht zurück).`,"telegram.days":`{count} Tage`,"telegram.threadDaysConfirm":`{count} Threads löschen?`,"telegram.threadDaysConfirm#one":`{count} Thread löschen?`,"telegram.threadDaysConfirmDesc":`Ihre Sitzungen sind länger inaktiv als das neue Limit: Ihre Threads und die darin enthaltenen Nachrichten werden aus Telegram gelöscht. Die Sitzungen bleiben in der Web-Oberfläche und bekommen mit ihrer nächsten Nachricht einen neuen Thread.`,"telegram.threadDaysConfirmOk":`Threads löschen`,"telegram.thread.session":`Sitzung`,"telegram.sync":`Threads synchronisieren`,"telegram.unlink":`Telegram trennen`,"telegram.unlinkDesc":`Vergisst das Bot-Token, den verknüpften Chat und die Threads. Die Sitzungen bleiben in der Web-Oberfläche.`,"telegram.unlinkConfirm":`Telegram trennen?`,"telegram.twoStepPassword":`Die Anmeldung in zwei Schritten ist aktiv: Wenn du die Verknüpfung löst, den Bot wechselst oder einen anderen Chat verknüpfst, wird sie für diesen Chat entfernt. Deshalb ist dein aktuelles Passwort nötig.`,"telegram.topicsOffDesc":`Alles funktioniert im Hauptchat. Für einen Thread pro Sitzung aktiviere den Threaded Mode für den Bot:`,"telegram.topicsStillOff":`Threads sind für diesen Bot weiterhin deaktiviert: Prüfe den Threaded Mode in @BotFather.`,"telegram.retry":`Erneut versuchen`,"telegram.changeBot":`Bot wechseln`,"telegram.changeBotHint":`Füge das Token eines anderen Bots oder das neue Token dieses Bots ein. Nichts ändert sich, bis das Token geprüft ist; ein anderer Bot muss erneut verknüpft werden.`,"telegram.newLink":`Neuer Link`,"telegram.expiresIn":`Noch {time} gültig`,"telegram.expired":`Dieser Link ist abgelaufen`,"telegram.expiredDesc":`Ein Link ist 15 Minuten gültig. Erstelle einen neuen und öffne ihn dann in Telegram.`,"telegram.startEarly":`Hast du in Telegram schon auf Start gedrückt? Öffne jetzt diesen Link (oder scanne den Code): Er sendet den Code.`,"telegram.relink":`Anderen Chat verknüpfen`,"telegram.relinkDesc":`Öffne diesen Link mit dem Telegram-Konto, das du verwenden willst: Er ersetzt den verknüpften Chat (der Bot bleibt derselbe).`,"telegram.newToken":`Neues Bot-Token`,"telegram.tokenRejected":`Telegram hat das Bot-Token abgelehnt`,"telegram.tokenRejectedDesc":`Das Token wurde in @BotFather widerrufen oder ersetzt: Der Bot empfängt nichts mehr. Füge das neue Token ein (derselbe Bot: Chat und Threads bleiben erhalten).`,"telegram.removeWebhook":`Webhook entfernen`,"telegram.err.webhook_set":`Dieser Bot sendet seine Nachrichten an einen Webhook: Ein anderes Programm nutzt ihn`,"telegram.err.webhookHelp":`Entferne den Webhook, um den Bot hier zu verwenden (das andere Programm erhält seine Nachrichten dann nicht mehr), oder erstelle mit @BotFather einen eigenen Bot.`,"telegram.err.conflict":`Ein anderes Programm (n8n, Hermes, OpenClaw…) nutzt diesen Bot bereits: Beende es oder erstelle mit @BotFather einen eigenen Bot.`,"telegram.err.webhook_check_failed":`Es konnte nicht geprüft werden, ob ein anderes Programm diesen Bot nutzt. Versuche es gleich noch einmal.`,"telegram.err.unreachable":`Telegram ist nicht erreichbar. Versuche es gleich noch einmal.`,"telegram.pollErrorTitle":`Nachrichtenempfang`,"telegram.syncErrorTitle":`Thread-Synchronisierung`,"telegram.lastPoll":`Letzte Antwort von Telegram`,"telegram.never":`nie`,"telegram.testProblems":`Testnachricht gesendet, aber:`,"telegram.testNotSent":`Die Testnachricht wurde nicht gesendet:`,"backup.whyTitle":`Warum ein Backup?`,"backup.why":`Deine Gedächtnis-Dateien machen Harness auf Dauer nützlich. Wenn dieser Server ausfällt, kann der Installer sie mit einem Backup in einer Minute auf einem neuen wiederherstellen. Es wird nur eine Whitelist von Textdateien hochgeladen, und ein Scanner blockiert alles, was wie ein Schlüssel aussieht.`,"backup.gh1":`Erstelle ein „fine-grained“ Token unter`,"backup.gh2":`Repository-Zugriff: „All repositories“, wenn das Repository für dich erstellt werden soll, sonst nur das Backup-Repository.`,"backup.gh3":`Berechtigungen:`,"backup.gh3b":`(Letztere nur, um das Repository zu erstellen).`,"backup.gh4":`Generiere das Token, kopiere es und füge es unten ein.`,"backup.repo":`Repository`,"backup.repoHint":`owner/name – es muss privat sein.`,"backup.repoInvalid":`Verwende die Form owner/name.`,"backup.token":`GitHub-Token`,"backup.tokenRequired":`Füge das GitHub-Token ein.`,"backup.create":`Privates Repository für mich erstellen`,"backup.createHint":`Falls es noch nicht existiert. Erfordert die Berechtigung Administration.`,"backup.connect":`Prüfen und speichern`,"backup.configFailed":`GitHub hat den Zugriff verweigert.`,"backup.notPrivate":`Dieses Repository ist öffentlich: Das Backup weigert sich, dorthin zu pushen.`,"backup.connected":`Backup-Repository verbunden`,"backup.private":`Privat`,"backup.runFirst":`Erstes Backup starten`,"backup.runNow":`Jetzt sichern`,"backup.runOk":`Backup abgeschlossen`,"backup.runOkDesc":`{files} Dateien, Commit {commit}.`,"backup.runFailed":`Backup fehlgeschlagen`,"backup.repository":`Repository`,"backup.repositoryDesc":`Wohin dein Gedächtnis hochgeladen wird.`,"backup.settings":`Zeitplan und Inhalt`,"backup.schedule":`Zeitplan`,"backup.scheduleHint":`Cron-Ausdruck, in deiner Zeitzone.`,"backup.scheduleInvalid":`Ungültiger Cron-Ausdruck.`,"backup.include":`Enthaltene Dateien`,"backup.includeHint":`Ausgegraute Muster sind immer enthalten. Füge Globs relativ zum Workspace hinzu.`,"backup.always":`Immer enthalten`,"backup.addGlob":`Muster hinzufügen`,"backup.history":`Verlauf`,"backup.historyDesc":`Beim Wiederherstellen werden die aktuellen Dateien zuerst in den Papierkorb gelegt.`,"backup.noHistory":`Noch kein Backup`,"backup.noHistoryDesc":`Durchläufe erscheinen hier.`,"backup.filesCount":`{count} Dateien`,"backup.filesCount#one":`{count} Datei`,"backup.changedCount":`{count} geändert`,"backup.restore":`Wiederherstellen`,"backup.restoreTitle":`Dieses Backup wiederherstellen?`,"backup.restoreDesc":`Dateien der Whitelist, geplante Jobs und Einstellungen werden durch diese Version ersetzt. Die aktuellen Dateien werden zuerst in den Papierkorb verschoben.`,"backup.restored":`{count} Dateien wiederhergestellt`,"backup.restored#one":`{count} Datei wiederhergestellt`,"backup.forget":`Backup trennen`,"backup.forgetDesc":`Vergisst das Repository und das Token. Das Repository selbst wird nicht gelöscht.`,"backup.forgetConfirm":`Backup trennen?`,"mcp.whatTitle":`MCP-Server geben Claude neue Werkzeuge`,"mcp.whatExplain":"Ein Server, der für „Jede Sitzung“ hinzugefügt wurde, ist überall verfügbar; wird er einem Thema hinzugefügt, nur in den Sitzungen dieses Themas. Geheimnisse bleiben in Einstellungen → Schlüssel und werden als ${KEY_NAME} referenziert. Du kannst auch einfach Claude in einem Thema fragen: „verbinde den MCP …“.","mcp.servers":`MCP-Server`,"mcp.autoTitle":`Laden`,"mcp.auto":`MCP-Server nur laden, wenn eine Sitzung sie braucht`,"mcp.autoHint":"Jeder geladene Server kostet bei jeder Nachricht Tokens und verlangsamt den Start eines Durchlaufs. Wenn aktiviert, bekommt eine Sitzung die Server, die ihr Thema schon genutzt hat, die in deiner Nachricht genannten und die, die ihrem Thema hinzugefügt wurden; Claude kann einen weiteren anfordern (`maxxing mcp load`) und Harness macht von selbst weiter. Wird ein claude.ai-Connector benötigt, wird wie bisher alles geladen. Die Werkzeuge des Harness-Browsers und deiner Geräte sind immer da, wenn ein Durchlauf sie nutzen kann.","mcp.serversDesc":`Die Server, die Claude Code in diesem Workspace lädt.`,"mcp.checkedAt":`Status geprüft {when}.`,"mcp.check":`Prüfen`,"mcp.checking":`Wird geprüft…`,"mcp.add":`Server hinzufügen`,"mcp.addDesc":`Die Adresse (oder der Befehl) steht in der Dokumentation des Dienstes.`,"mcp.empty":`Kein MCP-Server`,"mcp.emptyDesc":`Füge hier einen hinzu oder frage Claude in dem Thema, das ihn braucht.`,"mcp.name":`Name`,"mcp.where":`Wo`,"mcp.whereHint":`Jede Sitzung oder nur die Sitzungen eines Themas.`,"mcp.searchTopic":`Thema suchen`,"mcp.everywhere":`Jede Sitzung`,"mcp.stateCol":`Status`,"mcp.type":`Typ`,"mcp.typeHttp":`Adresse (URL)`,"mcp.typeStdio":`Lokales Programm`,"mcp.url":`Adresse`,"mcp.command":`Befehl`,"mcp.headers":`Header (optional)`,"mcp.env":`Umgebungsvariablen (optional)`,"mcp.addLine":`Zeile hinzufügen`,"mcp.insertKey":`Schlüssel aus dem Tresor einfügen`,"mcp.noKeys":`Kein Schlüssel in Einstellungen → Schlüssel`,"mcp.keysHint":"Ein als ${KEY_NAME} geschriebener Schlüssel wird beim Start der Sitzung aus dem Tresor gelesen (er wird den Sitzungen automatisch bereitgestellt). Server mit einem Button „Verbinden“ brauchen keinen Schlüssel.","mcp.literalWarn":"Das sieht nach einem Token im Klartext aus: Leg es besser in Einstellungen → Schlüssel ab und schreibe ${KEY_NAME}.","mcp.literal":`Token im Klartext`,"mcp.nameInvalid":`Nur Buchstaben, Ziffern, „.“, „_“ und „-“.`,"mcp.urlInvalid":`Die Adresse beginnt mit https://`,"mcp.commandRequired":`Gib den Befehl ein, der den Server startet.`,"mcp.added":`{name} hinzugefügt`,"mcp.addedExposed":`{name} hinzugefügt - Schlüssel, die jetzt den Sitzungen bereitgestellt werden: {keys}`,"mcp.state.connected":`Verbunden`,"mcp.state.needs_auth":`Zu verbinden`,"mcp.state.failed":`Fehler`,"mcp.state.pending":`Zu genehmigen`,"mcp.state.unknown":`Nicht geprüft`,"mcp.connect":`Verbinden`,"mcp.reconnect":`Erneut verbinden`,"mcp.connectTitle":`{name} verbinden`,"mcp.connectDesc":`Nur einmal, in vier Schritten: Die Verbindung bleibt danach für alle Sitzungen erhalten.`,"mcp.preparing":`Anmeldeseite wird vorbereitet…`,"mcp.step1":`Öffne die Anmeldeseite des Dienstes`,"mcp.openLogin":`Anmeldeseite öffnen`,"mcp.step2":`Melde dich bei {service} an und akzeptiere`,"mcp.step3":`Du landest auf einer Fehlerseite: Das ist normal`,"mcp.step3Desc":`Der Dienst leitet dich auf eine Adresse des Harness-Servers ("localhost") weiter, die dein Browser nicht öffnen kann, daher zeigt er "Diese Website ist nicht erreichbar". Die Verbindung ist noch nicht abgeschlossen: Der Code steckt in der Adresse.`,"mcp.browserError":`Diese Website ist nicht erreichbar - localhost hat die Verbindung abgelehnt.`,"mcp.step3Copy":`Kopiere die gesamte Adresse aus der Adressleiste (klicke darauf, dann Ctrl+C / ⌘C). Auf dem Handy: Adresse lange gedrückt halten, Kopieren.`,"mcp.step4":`Komm hierher zurück und füge sie ein`,"mcp.paste":`Einfügen`,"mcp.pasteDenied":`Der Browser hat das abgelehnt: Füge sie mit Ctrl+V / ⌘V in das Feld ein.`,"mcp.noCode":`Diese Adresse enthält kein "code=": Kopiere nach dem Akzeptieren die Adresse der Fehlerseite.`,"mcp.whyTitle":`Warum dieses Kopieren und Einfügen?`,"mcp.whyBody":`Claude Code, das auf deinem Server läuft, wartet auf die Antwort des Dienstes an einer lokalen Adresse des Servers. Der Dienst kann deinen Browser nur an diese Adresse zurückschicken, die nur auf dem Server existiert. Indem du sie einfügst, gibst du den Code an Claude Code weiter, das die Verbindung abschließt. Das funktioniert bei jedem Zugang (Domain, Tailscale) und braucht nichts weiter. Mach es innerhalb weniger Minuten: Der Code läuft ab.`,"mcp.finish":`Abschließen`,"mcp.retry":`Erneut versuchen`,"mcp.connected":`{name} ist verbunden`,"mcp.chatHint":`Der Agent braucht diese Verbindung. Sag ihm danach, dass er es erneut versuchen soll.`,"mcp.chatConnected":`{name} war bei der letzten Prüfung verbunden: Verbinde es erneut, falls der Agent weiterhin danach fragt.`,"mcp.remove":`Entfernen`,"mcp.removeTitle":`{name} entfernen?`,"mcp.removeDesc":`Claude hat dort dann keine Tools mehr. Die Schlüssel im Tresor bleiben erhalten.`,"keys.vault":`Tresor`,"keys.vaultDesc":`Die Werte verlassen den Server nie, außer du lässt sie anzeigen.`,"keys.add":`Schlüssel hinzufügen`,"keys.edit":`Schlüssel bearbeiten`,"keys.dialogDesc":`Gespeichert in der Secrets-Datei des Servers (Modus 600).`,"keys.name":`Name`,"keys.nameHint":`Im Stil einer Umgebungsvariable: OPENAI_API_KEY.`,"keys.nameInvalid":`Buchstaben, Ziffern und Unterstriche, beginnend mit einem Buchstaben.`,"keys.value":`Wert`,"keys.valueKeep":`Leer lassen, um den aktuellen Wert zu behalten.`,"keys.valueRequired":`Gib einen Wert ein.`,"keys.exists":`Ein Schlüssel mit diesem Namen existiert bereits: Öffne ihn mit Bearbeiten, um ihn zu ändern.`,"keys.note":`Notiz`,"keys.notePlaceholder":`Wofür er gedacht ist, woher er stammt`,"keys.noNote":`Keine Notiz`,"keys.expose":`Für Harness-Sitzungen bereitstellen`,"keys.exposeShort":`Bereitgestellt`,"keys.unexpose":`Nicht mehr bereitstellen`,"keys.scope":`Themen:`,"keys.scopeAll":`alle`,"keys.scopeCount":`{count} Themen`,"keys.scopeCount#one":`{count} Thema`,"keys.scopeChoose":`Auswählen`,"keys.scopeClear":`Alle`,"keys.scopeEmpty":`Noch kein Projekt.`,"keys.scopeHint":`Nur die Sitzungen und geplanten Jobs der angehakten Projekte und Themen erhalten diesen Schlüssel. Nichts angehakt: alle Themen. Agenten behalten ihre eigene Schlüsselliste.`,"keys.exposeDesc":`Wird bei jedem Harness-Durchlauf als Umgebungsvariable exportiert. Erweiterungen lesen Schlüssel auch ohne das: Lass es deaktiviert, außer Sitzungen brauchen die Variable.`,"keys.exposeTitle":`Bereitgestellte Schlüssel`,"keys.exposeExplain":`Ein bereitgestellter Schlüssel steht Harness als Umgebungsvariable (z. B. $OPENAI_API_KEY) in jeder Sitzung und jedem Cron zur Verfügung, sodass Skripte ihn nutzen können, ohne dass der Wert in einem Prompt auftaucht. Harness kann ihn trotzdem lesen: Stelle nur bereit, was Sitzungen brauchen.`,"keys.reveal":`Anzeigen`,"keys.copied":`{name} kopiert`,"keys.added":`Schlüssel hinzugefügt`,"keys.updated":`Schlüssel aktualisiert`,"keys.deleteTitle":`{name} löschen?`,"keys.deleteDesc":`Skripte und Sitzungen, die ihn nutzen, funktionieren nicht mehr.`,"keys.empty":`Noch keine Schlüssel`,"keys.emptyDesc":`Speichere API-Schlüssel und Tokens hier statt in Dateien.`,"keyfiles.title":`Dateien`,"keyfiles.desc":`Ein Keystore, eine Service-Account-JSON, ein Zertifikat: auf dem Server aufbewahrt, nie angezeigt und nicht herunterladbar.`,"keyfiles.add":`Datei hinzufügen`,"keyfiles.edit":`Datei bearbeiten`,"keyfiles.dialogDesc":`Auf dem Server in einem privaten Ordner gespeichert (Modus 600), höchstens 1 MiB.`,"keyfiles.nameHint":`Im Stil einer Umgebungsvariable: ANDROID_KEYSTORE. Wird mit den Schlüsseln geteilt: Ein Name ist entweder ein Schlüssel oder eine Datei.`,"keyfiles.file":`Datei`,"keyfiles.fileHint":`Jeder Dateityp, bis zu 1 MiB.`,"keyfiles.fileKeep":`Leer lassen, um die aktuelle Datei zu behalten ({filename}).`,"keyfiles.choose":`Datei auswählen`,"keyfiles.replace":`Datei ersetzen`,"keyfiles.noneChosen":`Keine Datei ausgewählt`,"keyfiles.expose":`Pfad für Harness-Sitzungen bereitstellen`,"keyfiles.exposeDesc":`Die Umgebungsvariable {name} enthält den Pfad der Datei (nicht ihren Inhalt) in jeder Harness-Sitzung und jedem Shell-Cron-Job.`,"keyfiles.exposeTip":"${name} enthält den Dateipfad","keyfiles.added":`Datei hinzugefügt`,"keyfiles.updated":`Datei aktualisiert`,"keyfiles.deleteTitle":`{name} löschen?`,"keyfiles.deleteDesc":`Die Datei wird vom Server gelöscht. Skripte und Sitzungen, die sie nutzen, funktionieren nicht mehr.`,"keyfiles.empty":`Noch keine Dateien`,"keyfiles.emptyDesc":`Speichere hier einen Keystore, eine Service-Account-JSON oder ein Zertifikat statt in einem Projektordner.`,"keyfiles.safety":`Sichere Speicherung: Die Dateien bleiben außerhalb des Backups, von Git und von Gedächtnisdateien, und nichts auf dieser Seite erlaubt es, sie wieder auszulesen. Das ist keine Isolation gegenüber einer Sitzung: Sitzungen laufen mit demselben Benutzer wie der Server, daher kann eine Sitzung, der der Pfad gegeben wird, die Datei lesen.`,"keyfiles.err.invalidName":`Großbuchstaben, Ziffern und Unterstriche, beginnend mit einem Buchstaben (2 bis 64 Zeichen).`,"keyfiles.err.reservedName":`Dieser Name ist vom System reserviert: Wähle einen anderen.`,"keyfiles.err.nameTaken":`Dieser Name wird bereits von einem Textschlüssel verwendet: Wähle einen anderen.`,"keyfiles.err.nameTakenKey":`Dieser Name wird bereits von einer Datei verwendet: Wähle einen anderen.`,"keyfiles.err.exists":`Eine Datei mit diesem Namen existiert bereits: Öffne sie mit Bearbeiten, um sie zu ersetzen.`,"keyfiles.err.fileRequired":`Wähle eine Datei.`,"keyfiles.err.empty":`Diese Datei ist leer.`,"keyfiles.err.tooLarge":`Diese Datei ist zu groß: maximal 1 MiB.`,"keyfiles.err.invalidNote":`Die Beschreibung enthält Zeichen, die nicht gespeichert werden können (Steuerzeichen): Entferne sie.`,"keyfiles.err.unsupportedType":`Der Server hat das Format des Uploads abgelehnt. Lade die Seite neu und versuche es erneut.`,"keyfiles.clear":`Gewählte Datei entfernen`,"keyfiles.keepCurrent":`Aktuelle Datei behalten`,"features.maxxing":`Maxxing-Modus (Beta)`,"features.maxxingDesc":`Ein „⚡ Maxxing“-Schalter auf der Seite Sitzungen (Alt+M), den du in jedem Browser einzeln aktivierst: Sobald eine Sitzung fertig ist, rückt sie allein nach vorn und ersetzt die anderen Spalten, damit du sofort das Nächste eintippen kannst. Ausgeschaltet kommen deine Spalten zurück.`,"system.health":`Zustand`,"system.healthDesc":`Wird alle 30 Sekunden aktualisiert.`,"system.cpuPriorities":`CPU-Prioritäten`,"system.cpuPrioritiesDesc":`Wenn der Prozessor ausgelastet ist, hat das, was du gerade ansiehst, Vorrang; schwere Arbeiten (Renderings, geplante Jobs) werden etwas langsamer, aber nie gestoppt.`,"system.disk":`Speicherplatz`,"system.diskDesc":`Gib den Platz frei, den Caches, alte Versionen und Logs belegen. Deine Projekte und Dateien werden nie angetastet.`,"system.diskUsed":`{used} von {total} belegt · {free} frei`,"system.cleanup":`Platz freigeben`,"system.cleanupClaude":`Mit Claude aufräumen`,"system.cleanupDesc":`Nur, was von selbst wiederkommt oder was du auswählst. Projekte, Anhänge und Renderings bleiben: „Mit Claude aufräumen“ sieht sie sich gemeinsam mit dir an.`,"system.cleanupScanning":`Wird gemessen…`,"system.cleanupNothing":`Nichts freizugeben: Alles ist schon sauber.`,"system.cleanupRun":`{size} freigeben`,"system.cleanupDone":`{size} freigegeben`,"system.cleanupFailed":`Einige Teile konnten nicht aufgeräumt werden: {parts}`,"system.cleanup.leftovers":`Alte Versionen und Überreste`,"system.cleanup.leftoversDesc":`Frühere Versionen der Komponenten, nicht mehr genutzte Browser, temporäre Dateien, zu große Logs.`,"system.cleanup.caches":`Download-Caches`,"system.cleanup.cachesDesc":`uv-, npm-, pip- und npx-Caches: Werden beim nächsten Bedarf erneut heruntergeladen. Was ein laufendes Tool nutzt, bleibt.`,"system.cleanup.journal":`Systemlogs`,"system.cleanup.journalDesc":`Das systemd-Journal, gekürzt auf die letzten 200 MB.`,"system.cleanup.apt":`Heruntergeladene Systempakete`,"system.cleanup.aptDesc":`Pakete, die apt bereits installiert hat (apt-get clean).`,"system.cleanup.previews":`Videovorschauen und Vorschaubilder`,"system.cleanup.previewsDesc":`Leichtere Kopien von Videos für den Player und Vorschaubilder von Dateien: Werden beim Anzeigen neu erstellt (etwas Rechenleistung). Ein Video, das in den letzten 30 Min. abgespielt wurde, bleibt.`,"system.cleanup.trash":`Papierkorb von Harness`,"system.cleanup.trashDesc":`Gelöschte Themen, Sitzungen und Dateien: Sie können danach nicht mehr wiederhergestellt werden.`,"system.cleanupPrompt":"Prüfe den Speicherplatz dieses Servers und hilf mir, ihn sauber freizugeben.\n\n1. Zustand: `df -h` und `free -h`, dann die größten Ordner (`du -xh --max-depth=2 / 2>/dev/null | sort -h | tail -40`), und sieh dir die größten genauer an. Einstellungen → System → Platz freigeben kümmert sich bereits um die Download-Caches, alte Komponentenversionen, das Systemjournal, apt-Pakete, Videovorschauen und den Papierkorb von Harness: Lass diese beiseite.\n2. Gehe jedes Projekt und Thema des Arbeitsbereichs durch: Anhänge, Video- und Audio-Renderings, Exporte, `node_modules`, Python-Umgebungen, Builds, große Git-Repositories, vergessene separate Kopien, Duplikate. Sieh dir auch die Caches anderer Tools an (`~/.cache/*`, heruntergeladene Modelle), Logs und alte Dateien in `/tmp`.\n3. Finde für jedes große Element heraus, woher es kommt: welches Projekt, welches Tool oder welcher geplante Job es erstellt hat (Daten, Inhalt, Gedächtnis des Themas, Crons) und ob es noch wächst.\n4. Gib mir eine nach Größe sortierte Tabelle: Pfad, Größe, Herkunft, kommt von selbst wieder oder nicht, dein Vorschlag (löschen, anderswohin verschieben, behalten) und der gewonnene Platz.\n5. Lösche nichts ohne mein OK: Stell mir alle deine Fragen auf einmal. Schlage bei dem, was ständig wiederkommt, vor, die Ursache zu beheben (ein Größenlimit, eine Bereinigung im Skript oder Job, der es erzeugt).\n6. Halte am Ende im Gedächtnis des passenden Themas fest, was wir beschlossen haben (was bleibt, was aufgeräumt wird).","system.claudeAuth":`Claude-Authentifizierung`,"system.notConnected":`Nicht verbunden`,"system.backupAge":`Letztes Backup`,"system.never":`Nie`,"system.hoursAgo":`vor {n} h`,"system.failedLogins":`Fehlgeschlagene Anmeldungen (1 h)`,"system.load":`Durchschnittliche Auslastung`,"system.services":`Dienste`,"system.servicesDesc":`systemd-Units, die für Harness Maxxing wichtig sind.`,"system.disabled":`Deaktiviert`,"system.start":`Starten`,"system.stop":`Stoppen`,"system.restart":`Neu starten`,"system.stopTitle":`{name} stoppen?`,"system.restartTitle":`{name} neu starten?`,"system.serviceConfirm":`Laufende Arbeit, die dieser Dienst bearbeitet, kann unterbrochen werden.`,"system.selfRestart":`Die Oberfläche ist für ein paar Sekunden offline und verbindet sich von selbst wieder. Laufende Durchläufe von Harness sind davon nicht betroffen.`,"system.actionDone":`{name}: erledigt`,"system.logs":`Protokolle`,"system.unit":`Dienst`,"system.lines":`{n} Zeilen`,"system.linesLabel":`Anzahl der Zeilen`,"system.noLogs":`Keine Protokollzeilen.`,"system.logSearch":`In den Zeilen suchen…`,"system.logLevelLabel":`Level`,"system.logLevel.all":`Alle Zeilen`,"system.logLevel.warning":`Warnungen und Fehler`,"system.logLevel.error":`Nur Fehler`,"system.logSinceLabel":`Zeitraum`,"system.logSince.all":`Beliebiger Zeitraum`,"system.logSince.1h":`Letzte Stunde`,"system.logSince.24h":`Letzte 24 Stunden`,"system.logSince.7d":`Letzte 7 Tage`,"system.logMatched":`{shown} von {matched} passenden Zeilen angezeigt, die neuesten.`,"system.logTruncated":`Es wurden nur die neuesten {n} Zeilen des Journals gelesen: Wähle einen kürzeren Zeitraum.`,"system.metrics":`Metriken für ein Monitoring-Tool`,"system.metricsDesc":`Für Prometheus, Grafana oder ein anderes Monitoring-System, das du schon nutzt: Tokens, Kosten, Durchläufe, Budget, geplante Jobs und Serverzustand an einer Adresse. Aus, solange du keins nutzt.`,"system.metricsOn":`/metrics bereitstellen`,"system.metricsOnDesc":`Nur mit einem geheimen Token lesbar. Kein Sitzungstitel, keine Nachricht und keine Datei ist darin enthalten.`,"system.metricsTokenOnce":`Token, nur dieses eine Mal angezeigt: Trag ihn jetzt in dein Monitoring-Tool ein (Authorization: Bearer …).`,"system.metricsTokenHint":`Der Token wurde bei der Erstellung angezeigt. Verloren? Erstelle einen neuen: Der alte funktioniert dann nicht mehr.`,"system.metricsNewToken":`Neuer Token`,"system.metricsNewTokenConfirm":`Der aktuelle Token funktioniert sofort nicht mehr: Dein Monitoring-Tool braucht den neuen.`,"system.version":`Version`,"system.upToDate":`Aktuell`,"system.behind":`{n} Updates verfügbar`,"system.unknownLatest":`Neueste Version unbekannt`,"system.unknownLatestDesc":"GitHub war mit dem Update-Token nicht erreichbar. Führe `maxxing update --check` auf dem Server aus, um den Grund zu sehen (abgelaufenes Token, kein Netzwerk).","system.check":`Jetzt prüfen`,"system.checkFailed":`Die Prüfung ist fehlgeschlagen`,"system.checkedAt":`geprüft {when}`,"system.update":`Jetzt aktualisieren`,"system.updateTitle":`Harness Maxxing aktualisieren?`,"system.updateDesc":`Lädt die neue Version herunter, installiert Abhängigkeiten und startet den Dienst neu (etwa eine Minute). Deine Daten, dein Workspace und deine Erweiterungen bleiben erhalten.`,"system.updating":`Aktualisierung läuft…`,"system.restarting":`Server wird neu gestartet…`,"system.updated":`Update installiert`,"system.autoUpdate":`Selbst aktualisieren, wenn niemand da ist`,"system.autoUpdateHint":`Standardmäßig aus. Wenn aktiviert: Sobald eine neue Version erschienen ist, niemand auf der Oberfläche ist, nichts läuft (kein Durchlauf, kein Job, 10 Minuten lang nichts) und das Update deine Anpassungen nicht berührt, aktualisiert sich Harness selbst und startet dann für ein paar Sekunden neu. Andernfalls wartet es und sagt dir in den Benachrichtigungen Bescheid. Änderungen, die eine Version in deinem Workspace verlangt (Hinweise zum Update), werden dort nach dem Update ebenfalls angekündigt.`,"system.autoLast":`Letzte Prüfung {when}: {what}`,"system.autoTried":`Letztes von ihm gestartetes Update: {version}, {when}.`,"system.autoRes.started":`Update wurde gestartet.`,"system.autoRes.up_to_date":`Harness ist aktuell.`,"system.autoRes.needs_review":`die neue Version braucht dich (eine Anpassung oder eine nicht gespeicherte Änderung am Code). Nutze die Schaltfläche „Jetzt aktualisieren“.`,"system.autoRes.pending":`ein früheres Update wartet auf dich, bis es geklärt ist, wird nichts versucht.`,"system.autoRes.not_on_branch":`der Code liegt auf einem absichtlich gesetzten Commit, nicht auf einem Branch: er bleibt unangetastet.`,"system.autoRes.unavailable":`die neue Version konnte nicht gelesen werden (Netzwerk?). Neuer Versuch innerhalb von 30 Minuten.`,"system.autoRes.tried_recently":`diese Version wurde in den letzten 24 Stunden schon versucht. Nächster Versuch morgen.`,"system.autoRes.failed":`das Update konnte nicht gestartet werden. Nächster Versuch morgen, oder nutze die Schaltfläche „Jetzt aktualisieren“.`,"system.autoWhy.browser":`wartet, jemand ist auf der Oberfläche (ein offen gelassener Tab zählt).`,"system.autoWhy.turn":`wartet, eine Sitzung arbeitet.`,"system.autoWhy.queue":`wartet, eine Nachricht in einer Sitzung steht noch aus.`,"system.autoWhy.aside":`wartet, eine Zwischenfrage wird gerade beantwortet.`,"system.autoWhy.cron":`wartet, ein geplanter Job läuft.`,"system.autoWhy.recent":`wartet, eine Sitzung hat vor weniger als 10 Minuten gearbeitet.`,"system.autoWhy.update":`wartet, ein Update läuft bereits.`,"system.autoWhy.work":`wartet, es läuft gerade etwas.`,"system.updatedDesc":`Lade die Seite neu, um die neue Version zu nutzen.`,"system.customs":`{count} Anpassungen am Produktcode, die bei jedem Update übernommen werden`,"system.customs#one":`{count} Anpassung am Produktcode, die bei jedem Update übernommen wird`,"system.license":`Lizenz {key} ({kind}) - {email}`,"system.licenseKind.paid":`bezahlt`,"system.licenseKind.beta":`Beta`,"system.licenseKind.gift":`geschenkt`,"system.licenseKind.enterprise":`Enterprise`,"system.licenseUpdatesUntil":`Updates bis {date}`,"system.licenseUpdatesEnded":`Updates endeten am {date} – dieser Server läuft weiter mit seiner Version`,"system.licenseUpdatesForever":`Updates inklusive`,"system.licenseMoving":`Der Wechsel zu den GitHub-Updates steht noch aus: {error}. Neuer Versuch alle 6 Std.`,"system.movedToGit":`Updates von GitHub (stabiler Branch) seit {date}, wie bei jeder Installation. Schlüssel {key} bleibt erhalten.`,"system.pendingConflict":`Update {version} wartet auf Harness`,"system.pendingConflictDesc":`Deine Anpassungen kollidieren mit der neuen Version. Nichts wurde geändert: Die aktuelle Version läuft weiter. Harness kann sie im Projekt system (Thema harness) anpassen.`,"system.pendingRolledBack":`Update {version} wurde zurückgesetzt`,"system.pendingRolledBackDesc":`Die neue Version ist nicht gestartet, deshalb wurde die vorherige automatisch wiederhergestellt – nichts ist verloren. Bitte Harness im Projekt system (Thema harness), das zu prüfen.`,"system.askClaude":`Harness fragen`,"features.agentPreview":`Vorschau beim Darüberfahren`,"features.agentPreviewDesc":`Wenn du den Mauszeiger auf einem Agenten in einer Liste ruhen lässt, siehst du, was er gerade tut. Mit der Übersicht in Space zeigt die Karte auch seinen Raum.`,"push.title":`Mobile Benachrichtigungen`,"push.desc":`Erhalte „Harness ist fertig“ auf diesem Handy oder Computer, auch wenn die App geschlossen ist. Die Benachrichtigung enthält nur den Sitzungstitel und den Anfang der Antwort und wird von deinem eigenen Server gesendet.`,"push.here":`Auf diesem Gerät benachrichtigen`,"push.hereDesc":`Fragt den Browser nach der Erlaubnis und registriert dieses Gerät. Jeder abgeschlossene Durchlauf deiner Sitzungen meldet sich dann hier, außer dem, den du gerade ansiehst.`,"push.feed":`Aus den Benachrichtigungen`,"push.feedDesc":`Was auch auf den registrierten Geräten klingelt. Eine Anfrage, die auf dein OK wartet, kommt mit Erlauben und Ablehnen in der Benachrichtigung (Android und Computer; auf dem iPhone öffnest du sie mit einem Tipp). Warnungen sind die Hinweise und die Fehler: ein fehlgeschlagener Job, eine ungewöhnliche Ausgabe, eine Website, die nicht erreichbar ist.`,"push.feed.all":`Anfragen und Warnungen`,"push.feed.asks":`Nur Anfragen`,"push.feed.off":`Nichts`,"push.test":`Test senden`,"push.testSent":`Test gesendet: Er sollte in wenigen Sekunden ankommen.`,"push.testNone":`Der Test konnte an kein Gerät gesendet werden.`,"push.denied":`Benachrichtigungen sind für diese Website blockiert: Erlaube sie in den Browser-Einstellungen und versuche es dann erneut.`,"push.noWorker":`Die App ist noch nicht bereit für Benachrichtigungen: Lade die Seite neu und versuche es erneut.`,"push.unsupported":`Dieser Browser kann keine Benachrichtigungen empfangen, wenn die App geschlossen ist. Nutze auf Android Chrome, am Computer Chrome, Edge oder Firefox (HTTPS erforderlich).`,"push.install":`Füge die App auf dem iPhone und iPad zuerst zum Home-Bildschirm hinzu (Teilen, dann Zum Home-Bildschirm) und öffne sie dann von dort, um dies zu aktivieren.`,"push.device":`Gerät`,"push.thisOne":`dieses Gerät`,"push.remove":`Dieses Gerät entfernen`,"memory.title":`Bereinigung des zweiten Gehirns`,"memory.desc":`Hält jede memory.md kurz und gut geordnet: Duplikate werden zusammengeführt, Widersprüche aufgelöst, alter Verlauf zusammengefasst, Abschnitte sortiert. Läuft jede Nacht (Job „Memory compaction“) und auf Abruf.`,"memory.cleanNow":`Jetzt aufräumen`,"memory.limit":`Maximale Länge pro Datei`,"memory.limitDesc":`Längere oder schwerere Dateien (1 KB für 10 Zeilen: 100 Zeilen = 10 KB) werden komprimiert und neu organisiert, damit sie darunter passen (etwa 80 %, um Spielraum zu lassen). Eine Gedächtnisdatei wird bei jeder Änderung vollständig erneut an Claude gesendet: Eine kurze kostet weniger und Sitzungen werden seltener zusammengefasst.`,"memory.lines":`{count} Zeilen`,"memory.noLimit":`Kein Limit`,"memory.daily":`Nächtliche Bereinigung`,"memory.dailyDesc":`Der Job „Memory compaction“ läuft standardmäßig um 5:00 Uhr: Ändere die Uhrzeit oder schalte ihn in Crons aus.`,"memory.openCrons":`Crons öffnen`,"memory.files":`Gedächtnis-Dateien`,"memory.filesDesc":`Alle memory.md des Workspace.`,"memory.overCount":`{count} Dateien überschreiten {limit} Zeilen oder {size} - „Jetzt bereinigen“ behebt das.`,"memory.overCount#one":`1 Datei überschreitet {limit} Zeilen oder {size} - „Jetzt bereinigen“ behebt das.`,"memory.allUnder":`Alle Dateien haben weniger als {limit} Zeilen und {size}.`,"memory.none":`Noch keine Gedächtnis-Datei`,"memory.file":`Datei`,"memory.lineCount":`Zeilen`,"memory.size":`Größe`,"memory.started":`Bereinigung gestartet`,"memory.startedDesc":`Harness komprimiert die Gedächtnis-Dateien in einer neuen Sitzung.`,"stats.budget":`Tagesbudget`,"stats.budgetDesc":`Eine Obergrenze in Dollar pro Tag für den ganzen Server, zum Preis, den Claude Code für jeden Durchlauf angibt (bei einem Abo: was dieselben Durchläufe mit einem API-Schlüssel kosten würden).`,"stats.budgetField":`Budget pro Tag ($)`,"stats.budgetFieldDesc":`0 = kein Budget. Eine Benachrichtigung bei 80 %, ein Alarm bei Erreichen. Danach warten geplante Jobs und Agents bis morgen; deine eigenen Nachrichten und „Jetzt ausführen“ laufen weiterhin.`,"stats.budgetToday":`Heute`,"stats.budgetSpent":"${spent} von ${limit}","stats.budgetReached":`Budget erreicht: Geplante Jobs und Agents warten bis morgen.`,"stats.limitRetry":`Nach dem Nutzungslimit neu starten`,"stats.limitRetryDesc":`Ein geplanter Job oder ein Agent-Lauf, der durch das Nutzungslimit deines Claude-Abos gestoppt wurde, startet von selbst neu, sobald das Limit zurückgesetzt wird (nicht, wenn das mehr als einen Tag später ist).`,"stats.limitRetryDelay":`Verzögerung nach dem Zurücksetzen (Sekunden)`,"stats.limitRetryDelayDesc":`Wie lange nach dem Zurücksetzen der Neustart erfolgt, 0 bis 3600.`,"stats.alerts":`Warnungen`,"stats.alertsDesc":`Eine Benachrichtigung, wenn die Ausgaben vom üblichen Rahmen abweichen. Nichts wird gestoppt: Das übernimmt ein Budget.`,"stats.alertSpend":`Ein ungewöhnlicher Tag`,"stats.alertSpendDesc":`Heute kostet so viel wie das Vielfache eines üblichen Tages (der Median der letzten 14 Tage), für den ganzen Server oder für einen Agent.`,"stats.alertSpendTimes":`{n}-mal`,"stats.alertOff":`Aus`,"stats.alertTurn":`Ein teurer Durchlauf ($)`,"stats.alertTurnDesc":`Ein einzelner Durchlauf kostet mindestens diesen Betrag. 0 = keine Warnung.`,"stats.alertErrors":`Ein Durchlauf, der immer wieder fehlschlägt`,"stats.alertErrorsDesc":`Mindestens 8 Tool-Aufrufe eines Durchlaufs sind fehlgeschlagen, und mindestens die Hälfte davon.`,"stats.quota":`Nutzung des Claude-Tarifs`,"stats.quotaDesc":`Wie viel von den Limits deines Claude-Abos du verbraucht hast (die Woche und das 5-Stunden-Fenster, falls dein Tarif eines hat).`,"stats.quotaEnable":`Tarifnutzung anzeigen`,"stats.quotaEnableDesc":`Experimentell: wird über einen undokumentierten Anthropic-Endpunkt gelesen und kann ausfallen. Fügt auch das Dashboard-Widget hinzu.`,"stats.fiveHour":`Aktuelles 5-Stunden-Fenster`,"stats.plan":`Tarif: Claude {plan}`,"stats.noFiveHour":`Kein 5-Stunden-Fenster: Der Ultra-Tarif hat nur das Wochenlimit.`,"stats.sevenDay":`Diese Woche`,"stats.resets":`Zurücksetzung {at}`,"stats.stale":`Zuletzt bekannte Werte (der Endpunkt hat gerade nicht geantwortet).`,"stats.quotaUnavailable":`Die Tarifnutzung ist mit dieser Anmeldemethode nicht verfügbar.`,"stats.reason.no_oauth_credentials":`Melde Claude auf diesem Server an (Einstellungen -> Claude), um die Tarifnutzung zu lesen.`,"stats.reason.api_key":`Die Tarifnutzung gibt es nur bei einem Claude-Abo; dieser Server nutzt einen API-Schlüssel.`,"stats.reason.rate_limited":`Anthropic begrenzt, wie oft die Nutzung gelesen werden kann - nächste Abfrage {when}.`,"stats.reason.http_401":`Die Claude-Anmeldung wurde abgelehnt: Melde dich erneut an (Einstellungen -> Claude).`,"stats.reason.other":`Die Tarifnutzung konnte nicht gelesen werden ({code}).`,"stats.nextReading":`Nächste Abfrage {when}.`,"stats.tokens":`Tokens`,"stats.tokensDesc":`Gezählt über jeden Harness-Durchlauf, archivierte Sitzungen eingeschlossen. Das Tagesdiagramm beginnt mit dieser Version.`,"stats.empty":`Noch kein Harness-Durchlauf`,"stats.total":`Tokens`,"stats.turns":`{count} Durchläufe`,"stats.turns#one":`1 Durchlauf`,"stats.turnsCol":`Durchläufe`,"stats.inOut":`Eingabe / Ausgabe`,"stats.cache":`Cache gelesen / geschrieben`,"stats.cacheHint":`günstiges erneutes Lesen des Kontexts`,"stats.turnStart":`Start eines Durchlaufs (Median)`,"stats.turnStartHint":`erste Antwort nach {first} s · letzte {count} Durchläufe`,"stats.perDay":`Tokens pro Tag (30 Tage)`,"stats.groupBy":`Gruppieren nach`,"stats.byProject":`Projekt`,"stats.byTopic":`Thema`,"stats.bySession":`Sitzung`,"stats.byAgent":`Agent`,"stats.costCol":`Kosten`,"stats.export":`Diese Tabelle herunterladen, alle Zeilen:`,"stats.exportDays":`Pro Tag (CSV)`,"about.desc":`Kostenlos und fair source: derselbe Code für alle.`,"about.checkUpdates":`Nach Updates suchen`,"features.pagesDesc":`Alle Seiten der Seitenleiste in ihrer Reihenfolge. Die optionalen lassen sich abschalten: Die Seite wird dann ausgeblendet, gelöscht wird nichts.`,"features.thisBrowser":`Dieser Browser`,"features.tabs":`Tabs-Modus`,"features.tabsDesc":`Eine Sitzung auf dem Bildschirm, die geöffneten als Tabs darüber. Aus: Zonen-Modus, die Sitzungen nebeneinander. Auch oben rechts auf der Seite Sitzungen umschaltbar (Alt+T).`,"features.inSidebar":`In der Seitenleiste`,"features.badges":`Badges`,"features.badgesDesc":`Die Zähler neben den Seiten der Seitenleiste. Schalte einen aus, und seine Seite zeigt weder Zahl noch Punkt; die Zähler bleiben auf der Seite selbst. Ein Badge wird rot, wenn eines der gezählten Dinge ein Fehler ist.`,"features.badge.home":`Ungelesene Benachrichtigungen.`,"features.badge.sessions":`Sitzungen mit einer ungelesenen Antwort und solche, die gerade arbeiten.`,"features.badge.team":`Ungelesene Nachrichten.`,"features.badge.agents":`Neue Ergebnisse und wartende Freigaben.`,"features.alwaysOn":`Immer aktiv`,"features.page.dashboard":`Deine Startseite: Widgets, Aktivität von heute, was auf dich wartet.`,"features.page.sessions":`Deine Unterhaltungen mit Claude, nach Projekt und Thema.`,"features.page.files":`Die Dateien des Servers: durchsuchen, ansehen, hochladen, herunterladen.`,"features.page.agents":`Dauerhafte Helfer, die in einem Thema leben, jeder mit eigener Rolle und eigenem Gedächtnis, von Hand, zeitgesteuert, per Webhook oder über Telegram gestartet, innerhalb eines Tagesbudgets.`,"features.page.tasks":`Ein Board mit Dingen, die zu erledigen sind (Kanban, Woche, Kalender, Liste), das auch Claude liest und aktualisiert, mit eigenem Dashboard-Widget.`,"features.page.team":`Chatte mit Leuten, die ein eigenes Harness haben: Nachrichten, Gruppen, Umfragen und Dateien, von Server zu Server.`,"features.page.mail":`Deine Postfächer, hier gelesen, durchsucht und sortiert, und von Claude in deinen Sitzungen.`,"features.page.infra":`Jede Website, Datenbank, jeder Bucket, jede Domain und jeder Server, mit Status und Speicherort.`,"features.page.git":`Die Repositories des Servers und deines GitHub-Kontos, ihre Branches und Commits als Graph.`,"features.need.team":`Braucht eine https-Adresse im Internet (Domain-Modus).`,"features.need.mail":`Braucht ein Postfach mit IMAP/SMTP (Gmail mit App-Passwort, OVH…).`,"features.need.infra":`Dieser Server funktioniert so, wie er ist; Cloudflare und Hostinger brauchen ihren Schlüssel unter`,"features.need.git":`GitHub braucht den Schlüssel GITHUB_TOKEN unter`,"keys.gitSuggest":`Ein GitHub-Schlüssel liegt im Tresor: Die Git-Seite zeigt deine Repositories und ihre Graphen.`,"keys.gitSuggestOn":`Git-Seite anzeigen`,"appearance.theme":`Theme`,"appearance.themeDesc":`Das Aussehen der gesamten Oberfläche, Widgets inklusive. Farben und Schriften stellst du direkt darunter ein.`,"appearance.default":`Standard`,"appearance.solidDesc":`Einfarbige Flächen, klar und ruhig.`,"appearance.glassDesc":`Leisten, Menüs und Dialoge sind durchscheinend über einem Hintergrund in deiner Akzentfarbe.`,"appearance.options":`Optionen von {name}`,"appearance.optionsDesc":`Dunkel oder hell, die Akzentfarbe, der Hintergrund und die Schriften.`,"appearance.by":`von {name}`,"appearance.onSolid":`auf Matt`,"appearance.onGlass":`auf Glas`,"appearance.installedDesc":`Installiertes Theme.`,"appearance.unusable":`Nicht nutzbare Themes:`,"appearance.moreThemes":`Weitere Themes: für dich gemacht oder aus Community übernommen, von Harness installiert.`,"appearance.ask":`Harness fragen`,"appearance.askPrompt":`Ich hätte gern ein neues Theme für Harness Maxxing (skill maxxing-theme). Das habe ich im Kopf: `,"appearance.fixedMode":`Dieses Theme gibt es nur in diesem Modus.`,"appearance.ownAccent":`Von diesem Theme festgelegt.`,"appearance.css":`Erweitertes CSS`,"appearance.cssDesc":`Zusätzliche Stilregeln dieses Themes. Anders als seine Farben können sie nach einem Update falsch dargestellt werden: Schalte sie hier aus, wenn etwas kaputt aussieht.`,"appearance.cssStale":`Ausgeschaltet: Ein Update hat die Oberfläche verändert. Harness prüft sie und schaltet sie wieder ein.`,"appearance.cssVerify":`Harness um Prüfung bitten`,"appearance.cssVerifyPrompt":`Das erweiterte CSS meines Themes {id} wurde durch ein Update ausgeschaltet. Prüfe es gegen die aktuelle Oberfläche (skill maxxing-theme), korrigiere es bei Bedarf und schalte es dann wieder ein.`,"appearance.layout":`Layout`,"appearance.layoutDesc":`Abstände, Layout für Handy oder Computer und der erste Bildschirm auf dem Handy.`,"security.privacy":`Datenschutz`,"security.privacyDesc":`Der Präsentationsmodus verbirgt deine Daten, während du deinen Bildschirm teilst (das Augen-Symbol unten in der Seitenleiste).`,"about.version":`Version {version}`,"about.community":`Community`,"emoji.pick":`Emoji auswählen`,"emoji.search":`Emoji suchen`,"emoji.none":`Kein Emoji gefunden`,"emoji.clear":`Emoji entfernen`,"about.contact":`In Kontakt bleiben`,"import.restore":`Ein Backup des Gedächtnisses`,"import.restoreDesc":`Du wechselst den Server: Stelle das Backup des alten Servers aus seinem GitHub-Repository wieder her.`,"import.agentDesc":`Eine Agent-Datei (.md, Claude-Code-Format): Seite Agents -> Neuer Agent -> Importieren.`,"skills.where.workspace":`Workspace`,"skills.where.user":`Server`,"skills.slashOnly":`nur mit /{name}`,"skills.open":`Öffnen`,"skills.edit":`Mit Claude bearbeiten`,"skills.editPrompt":`Ändere den Skill {name} ({path}): `,"skills.publish":`Mit der Community teilen`,"skills.publishPrompt":`Bereite den Skill {name} ({path}) für die Harness-Maxxing-Community vor, gemäß https://harness-maxxing.com/community/publish.md: Prüfe, dass er keine persönlichen Daten, Pfade oder Geheimnisse enthält, und sag mir dann, was ich senden soll.`,"skills.search":`Skills durchsuchen`,"skills.mine":`Deine Skills`,"skills.mineDesc":`In ~/.claude/skills (alle Sitzungen), im Workspace oder in einem Projekt oder Thema (nur deren Sitzungen).`,"skills.new":`Neuer Skill`,"skills.newPrompt":`Erstelle einen Skill (im richtigen .claude/skills-Ordner), der `,"skills.emptyShipped":"Die mit Harness gelieferten Skills sind nicht auf diesem Server. `maxxing update` installiert sie erneut.","skills.noMatch":`Kein Skill passt.`,"skills.empty":`Noch keine eigenen Skills`,"skills.emptyDesc":`Bitte Claude, einen zu schreiben, wenn du oft dieselbe Art von Aufgabe wiederholst.`,"skills.shipped":`Mit Harness geliefert`,"skills.shippedDesc":`Wird bei jedem Update aktualisiert: Öffne sie zum Lesen, bearbeite sie nicht.`,"pkg.from":`Installiert von {source} am {date}`,"pkg.on":`Installiert am {date}`,"pkg.modified":`Dateien seit der Installation geändert`,"skills.community":`Skills, die andere Nutzer geteilt haben:`,"features.page.jarvis":`Ein einziger Assistent, mit dem du sprichst: Er legt Projekte und Themen an, übergibt die Arbeit an Sitzungen und Agents, holt deren Ergebnisse ab und führt das Gespräch weiter – mit einem Morgenbriefing und einem Gedächtnis, das er jede Nacht aufräumt.`,"features.need.jarvis":`Verbraucht mehr von deinem Claude-Tarif als reine Sitzungen: Jede Antwort, die aus einer Sitzung zurückkommt, ist ein zusätzlicher Jarvis-Durchlauf, dazu kommen ein Morgenbriefing und ein Nachtlauf (Sonnet, an ruhigen Tagen übersprungen). Schalte das Briefing oder den Nachtlauf in seinen Einstellungen aus, um weniger zu verbrauchen.`};export{e as default};